function launchpad(S, R) { const f = S.forms.launch, projects = S.launchTab === 'discover' ? R('discover', 'launch/discover') : null; return heading('Launchpad', 'De una idea a un token. Transparencia desde la primera transacción.', 'PULP / BUILD', button('Nuevo proyecto', 'new-project', 'plus')) + (S.launchTab==='discover'?hero('PULP / LAUNCHPAD','Tu idea merece<br><span>su propio espacio.</span>','Descubrí proyectos y prepará un token Solana. Suministro, metadata y autoridades visibles antes de firmar.','pulp-rocket','',true):'') + tab([['discover', 'Descubrir'], ['create', 'Crear token'], ['drafts', 'Mis borradores']], S.launchTab, 'launch-tab') + (S.launchTab === 'discover' ? `${hero("BUILD. LAUNCH. GROW.","La próxima idea.<br><span>El próximo Pulp.</span>","Dale forma a tu proyecto. Creá un token SPL con suministro y permisos explícitos. Emitir no crea un mercado ni recauda fondos automáticamente.","hero-launchpad",button("Crear un token","new-project","rocket"),true)}${notice('Los perfiles provienen de DEX Screener. <strong>No son proyectos revisados ni recomendaciones de inversión.</strong> Pulp no comprueba su legitimidad.')}<div class="b-heading"><div><h2 style="font-size:18px;margin:0">Proyectos publicados en Solana</h2></div>${button('Actualizar', 'retry', 'refresh', 'secondary', 'data-key="discover"')}</div>${dataView(projects, d => d.projects.length ? `<div class="b-projects">${d.projects.map((p, i) => `<article class="b-project"><div class="p-project-cover">${art(['scene-ecosystem','scene-octopus','scene-launch'][i%3])}<span>ILUSTRACIÓN PULP</span></div><div class="b-project-top"><span class="b-project-icon">${I('orbit')}</span><button class="b-icbtn" data-action="favorite" data-address="${e(p.tokenAddress)}" aria-label="${(S.workspace.favorites || []).includes(p.tokenAddress) ? 'Quitar de favoritos' : 'Guardar favorito'}">${I((S.workspace.favorites || []).includes(p.tokenAddress) ? 'heart' : 'star')}</button></div><h3>${e(short(p.tokenAddress, 7))}</h3><p>${e((p.description || 'Perfil publicado por un tercero. Revisá contrato, liquidez y distribución.').slice(0, 240))}</p><span class="b-mono">${e(p.tokenAddress)}</span><div class="b-actions">${button('Ver token', 'token-detail', 'chart', 'secondary', `data-mint="${e(p.tokenAddress)}"`)}${ext('DEX Screener', p.url, 'ghost')}</div></article>`).join('')}</div>` + source(d.source, d.observedAt) : empty('No hay perfiles disponibles', 'Reintentá la consulta más tarde. No se sustituyen por proyectos ficticios.', 'rocket'), 'discover')}` : S.launchTab === 'drafts' ? drafts(S) : `<div class="b-grid b-grid-aside">${panel('Configurar el token', 'rocket', body(`<form class="b-form" data-form="launch"><div class="b-form-row">${field('launch', 'name', 'Nombre', f.name, { placeholder: 'Pulp', attrs: 'required maxlength="32"' })}${field('launch', 'symbol', 'Ticker', f.symbol, { placeholder: 'PULP', attrs: 'required maxlength="10" pattern="[A-Za-z0-9]{2,10}"' })}</div><div class="b-form-row">${field('launch', 'supply', 'Suministro total', f.supply, { placeholder: '1000000000', attrs: 'required inputmode="decimal"' })}${field('launch', 'decimals', 'Decimales', f.decimals, { select: [[0, '0 · Unidades enteras'], [6, '6 · Estándar'], [9, '9 · Máxima precisión']] })}</div>${field('launch', 'description', 'Descripción para la metadata', f.description, { textarea: true, attrs: 'maxlength="500"', placeholder: 'Qué hace tu proyecto…' })}${field('launch', 'image', 'URL HTTPS del logo (metadata)', f.image, { placeholder: 'https://…/logo.png', help: 'Se incluye en el JSON exportado; Pulp no sube archivos a un servicio externo.' })}${field('launch', 'uri', 'URI HTTPS de metadata publicada', f.uri, { placeholder: 'https://…/metadata.json', attrs: 'maxlength="200"', help: 'Opcional. Sin URI, los wallets pueden mostrar solo la dirección. Con URI, la metadata on-chain será inmutable.' })}${checkbox('launch', 'fixed', 'Suministro fijo: revocar autoridad de emisión', f.fixed, 'La revocación es irreversible. La autoridad de congelación no se habilita.')}<div class="b-actions">${button('Exportar metadata', 'metadata', 'download', 'secondary')}${button('Guardar borrador', 'save-draft', 'document', 'secondary')}</div><div class="b-separator" style="margin:0"></div>${notice('El 100% del suministro se crea en tu wallet. <strong>No incluye vesting, distribución, pool, preventa ni liquidez.</strong> Nombre y ticker no son identificadores únicos.', 'warning')}<button class="btn btn-primary b-wide" type="submit" ${S.busy ? 'disabled' : ''}>${I('rocket', 'sm')}${S.owner ? 'Revisar creación on-chain' : 'Conectar wallet para crear'}</button></form>`))}${panel('Un lanzamiento sin sorpresas', 'shield', body(steps([['Probá primero en Devnet', 'Cambiá la red en Ajustes y usá SOL de prueba. No necesitás lanzar PULP en Mainnet para probar la app.'], ['Publicá la metadata', 'Exportá el JSON, alojalo en una URL pública permanente y pegá la URI antes de firmar.'], ['Revisá supply y autoridades', 'Verás la nueva dirección, destinatario, renta estimada y permisos antes de abrir la wallet.'], ['Liquidez es otra operación', 'Después de emitir, administrá el pool y su riesgo en Raydium. Para curvas y recaudación, usá LaunchLab.']]) + `<div class="b-separator"></div>${ext('Abrir LaunchLab', 'https://raydium.io/launchpad/')}`))}</div>`); }
